    fun getString(language: String, name: String): String? {
        val encoded = encodedStringMap[language]?.get(name) ?: return null
        return String(Base64.getDecoder().decode(encoded), Charsets.UTF_8)
    }

    fun getPlural(language: String, name: String): Map<String, String>? {
        val map = encodedPluralMap[language]?.get(name) ?: return null
        return map.mapValues { (_, encoded) ->
            String(Base64.getDecoder().decode(encoded), Charsets.UTF_8)
        }
    }

    fun stringKeys(language: String): Set<String> = encodedStringMap[language]?.keys.orEmpty()

    fun pluralKeys(language: String): Set<String> = encodedPluralMap[language]?.keys.orEmpty()

    fun getStringOrEnglish(language: String, key: String): String =
        getString(language, key)
            ?: getString(DEFAULT_LANGUAGE_IDENTIFIER, key)
            ?: error("No translation for key '$key' in '$language' or English.")

    fun getPluralOrEnglish(language: String, key: String): Map<String, String> =
        getPlural(language, key)
            ?: getPlural(DEFAULT_LANGUAGE_IDENTIFIER, key)
            ?: error("No plural translation for key '$key' in '$language' or English.")
}

@Composable
internal fun currentAppString(key: String, vararg args: Any): String =
    formatAppString(LocalAppLanguage.current, key, args)

@Composable
internal fun currentAppPlural(key: String, quantity: Int, vararg args: Any): String =
    formatAppPlural(LocalAppLanguage.current, key, quantity, args)

internal fun Context.appString(key: String, vararg args: Any): String =
    formatAppString(selectedAppLanguage(), key, args)

internal fun Context.appStringForLanguage(
    language: String,
    key: String,
    vararg args: Any
): String =
    formatAppString(language, key, args)

internal fun Context.appPlural(key: String, quantity: Int, vararg args: Any): String =
    formatAppPlural(selectedAppLanguage(), key, quantity, args)

private fun Context.selectedAppLanguage(): String =
    getSharedPreferences(APP_PREFERENCES_NAME, Context.MODE_PRIVATE)
        .getString(APP_LANGUAGE_KEY, DEFAULT_LANGUAGE_IDENTIFIER)
        ?: DEFAULT_LANGUAGE_IDENTIFIER

internal fun formatAppString(language: String, key: String, args: Array<out Any>): String =
    formatDictionaryText(
        TranslationDictionary.getStringOrEnglish(language, key),
        language,
        args
    )

internal fun formatAppPlural(
    language: String,
    key: String,
    quantity: Int,
    args: Array<out Any>
): String {
    val selectedPlural = TranslationDictionary.getPlural(language, key)
    val englishPlural = TranslationDictionary.getPlural(DEFAULT_LANGUAGE_IDENTIFIER, key)
    val quantityCategory = if (quantity == 1) "one" else "other"
    val pattern = selectedPlural?.get(quantityCategory)
        ?: selectedPlural?.get("other")
        ?: englishPlural?.get(quantityCategory)
        ?: englishPlural?.get("other")
        ?: error("No plural translation for key '$key' in '$language' or English.")
    val formatArgs = if (args.isNotEmpty()) args else arrayOf(quantity)
    return formatDictionaryText(pattern, language, formatArgs)
}

private fun formatDictionaryText(
    pattern: String,
    language: String,
    args: Array<out Any>
): String = if (args.isEmpty()) {
    pattern
} else {
    String.format(Locale.forLanguageTag(localeTagForLanguage(language)), pattern, *args)
}
